steps.body:
run: |
  python scripts/benchmark_noema005_summation.py \
    --sizes 128,512 --warmups 1 --repetitions 2 \
    --output "$RUNNER_TEMP/noema005-benchmark.json"
  python - "$RUNNER_TEMP/noema005-benchmark.json" <<'PY'
  import json
  from pathlib import Path
  import sys

  report = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
  expected_formats = {"binary32", "binary64", "decimal64", "decimal128"}
  if {case["format"] for case in report["cases"]} != expected_formats:
      raise SystemExit("NOEMA-005 benchmark format coverage mismatch")
  if len(report["cases"]) != 8:
      raise SystemExit("NOEMA-005 benchmark size/format case count mismatch")
  for case in report["cases"]:
      if not case["methods"]:
          raise SystemExit(f"No benchmark methods recorded for {case['format']}")
      for method in case["methods"]:
          if method["median_runtime_ns"] <= 0 or method["peak_traced_python_bytes"] < 0:
              raise SystemExit(f"Invalid benchmark measurement: {case['format']}/{method['method']}")
  print("NOEMA-005 runtime/memory benchmark smoke test OK")
  PY
